CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', camp text NOT NULL DEFAULT 'Kakuma', country text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', sms_opt_in boolean NOT NULL DEFAULT false, whatsapp_opt_in boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_own_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profile_own_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY profile_own_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('admin','caseworker')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_own ON public.user_roles FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE TABLE public.applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, assigned_caseworker uuid, full_name text NOT NULL, camp text NOT NULL, country text NOT NULL, identity_number text NOT NULL DEFAULT '', qualification_type text NOT NULL, institution text NOT NULL, graduation_year text NOT NULL DEFAULT '', authority text NOT NULL, stage integer NOT NULL DEFAULT 0 CHECK(stage BETWEEN 0 AND 5), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.applications TO authenticated;
GRANT ALL ON public.applications TO service_role;
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY application_read ON public.applications FOR SELECT TO authenticated USING(user_id = auth.uid() OR (assigned_caseworker = auth.uid() AND public.has_role(auth.uid(),'caseworker')) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY application_create ON public.applications FOR INSERT TO authenticated WITH CHECK(user_id = auth.uid() AND stage IN (0,1) AND assigned_caseworker IS NULL);
CREATE POLICY application_update ON public.applications FOR UPDATE TO authenticated USING ((user_id = auth.uid() AND stage = 0) OR (assigned_caseworker = auth.uid() AND public.has_role(auth.uid(),'caseworker')) OR public.has_role(auth.uid(),'admin')) WITH CHECK (user_id = auth.uid() OR (assigned_caseworker = auth.uid() AND public.has_role(auth.uid(),'caseworker')) OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.guard_application_update() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') AND NOT public.has_role(auth.uid(),'caseworker') AND auth.uid() IS NOT NULL THEN IF NEW.stage NOT IN (0,1) OR NEW.user_id <> OLD.user_id OR NEW.assigned_caseworker IS DISTINCT FROM OLD.assigned_caseworker THEN RAISE EXCEPTION 'Application status can only be changed by an authorized caseworker'; END IF; END IF; NEW.updated_at = now(); RETURN NEW; END $$;
CREATE TRIGGER guard_application_update BEFORE UPDATE ON public.applications FOR EACH ROW EXECUTE FUNCTION public.guard_application_update();
CREATE TABLE public.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, application_id uuid REFERENCES public.applications(id) ON DELETE SET NULL, name text NOT NULL, category text NOT NULL, storage_path text NOT NULL, size_bytes integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.documents TO authenticated;
GRANT ALL ON public.documents TO service_role;
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_read ON public.documents FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE POLICY documents_create ON public.documents FOR INSERT TO authenticated WITH CHECK(user_id = auth.uid() AND (application_id IS NULL OR EXISTS(SELECT 1 FROM public.applications a WHERE a.id = application_id AND a.user_id = auth.uid())) AND split_part(storage_path,'/',1) = auth.uid()::text);
CREATE POLICY documents_delete ON public.documents FOR DELETE TO authenticated USING(user_id = auth.uid());
CREATE FUNCTION public.create_rqrs_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'full_name','')); RETURN NEW; END $$;
CREATE TRIGGER on_rqrs_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_rqrs_profile();
CREATE INDEX applications_user_idx ON public.applications(user_id);
CREATE INDEX applications_caseworker_idx ON public.applications(assigned_caseworker);
CREATE INDEX documents_user_idx ON public.documents(user_id);
CREATE INDEX documents_application_idx ON public.documents(application_id);